#!/usr/bin/env bash

# installer animation uses setterm, needs TERM in terminfo; no real tty here, so honest 'dumb'
export TERM="${TERM:-dumb}"

THEME_DIR=$(realpath "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/MacTahoe-gtk-theme")

cd "$THEME_DIR" || { echo "Error: Could not find theme folder at $THEME_DIR"; exit 1; }

rm -f "$HOME/.config/gtk-4.0/gtk.css"
# install.sh compiles every css it installs (incl. rizzoo's _colors.scss); the
# separate parse-sass.sh only pre-generates unused css and fails on fresh clones
# because the *-temp.scss files it imports are generated by install.sh itself.
./install.sh -n Mac -d "$HOME/.themes" -c dark -o normal -l -f --darker
rc=$?

systemctl --user restart xdg-desktop-portal-gtk

exit "$rc"
